function shortcutFromEvent(event){let key=event.key;if(key===' ')key='Space';if(key==='+')key='Plus';if(key.length===1)key=key.toLowerCase();if(['Control','Meta','Alt','Shift','Dead','Unidentified'].includes(key))return null;const modifiers=[];if(event.ctrlKey||event.metaKey)modifiers.push('Mod');if(event.altKey)modifiers.push('Alt');if(event.shiftKey)modifiers.push('Shift');return [...modifiers,key].join('+')}
function normalizeShortcut(value){if(typeof value!=='string')return null;const parts=value.split('+').filter(Boolean);if(!parts.length)return null;let key=parts.pop();if(['Mod','Ctrl','Meta','Alt','Shift'].includes(key))return null;const modifiers=new Set();for(const modifier of parts){const normalized=['Ctrl','Meta'].includes(modifier)?'Mod':modifier;if(!['Mod','Alt','Shift'].includes(normalized)||modifiers.has(normalized))return null;modifiers.add(normalized)}if(key.length===1)key=key.toLowerCase();const order=['Mod','Alt','Shift'];return [...order.filter(modifier=>modifiers.has(modifier)),key].join('+')}
function formatShortcut(value){return value.split('+').map(key=>{const display={Mod:'Ctrl/Cmd',ArrowUp:'↑',ArrowDown:'↓',ArrowLeft:'←',ArrowRight:'→',Delete:'Supr',Backspace:'Retroceso',Space:'Espacio',Plus:'+'}[key];return display|| (key.length===1?key.toUpperCase():key)}).join(' + ')}
function loadEditorShortcuts(){try{const stored=localStorage.getItem('lyrics.editor.shortcuts.v1');if(!stored)return;const parsed=JSON.parse(stored);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new Error('Formato de atajos no válido.');for(const {id} of shortcutDefinitions){if(!Array.isArray(parsed[id]))continue;const normalized=parsed[id].map(normalizeShortcut);if(normalized.every(Boolean))editorShortcuts[id]=normalized}}catch(error){console.error('No se pudieron cargar los atajos personalizados:',error);toast('No se pudieron cargar los atajos guardados. Se usarán los valores disponibles.')}}
function saveEditorShortcuts(){try{localStorage.setItem('lyrics.editor.shortcuts.v1',JSON.stringify(editorShortcuts));return true}catch(error){console.error('No se pudieron guardar los atajos personalizados:',error);toast('No se pudieron guardar los atajos en este navegador.');return false}}
function renderShortcutSettings(){const container=$('#shortcutSettingsList');container.innerHTML=shortcutDefinitions.map(({id,label})=>`<div class="shortcut-row"><span class="shortcut-label">${esc(label)}</span><div class="shortcut-bindings">${editorShortcuts[id].length?editorShortcuts[id].map(value=>`<span class="shortcut-binding"><kbd>${esc(formatShortcut(value))}</kbd><button type="button" data-shortcut-remove="${id}" data-shortcut-value="${esc(value)}" aria-label="Quitar ${esc(formatShortcut(value))} de ${esc(label)}">×</button></span>`).join(''):'<span class="shortcut-empty">Sin asignar</span>'}</div><div class="shortcut-actions"><button type="button" class="shortcut-add" data-shortcut-add="${id}">Añadir</button><button type="button" class="shortcut-capture" data-shortcut-action="${id}">Cambiar</button></div></div>`).join('')}
function setShortcutCapture(button,append=false){capturingShortcut={id:button.dataset.shortcutAction||button.dataset.shortcutAdd,append};button.textContent='Presiona…'}
function shortcutIsUsed(shortcut,exceptId){return shortcutDefinitions.some(({id})=>id!==exceptId&&editorShortcuts[id].includes(shortcut))}
function insertNextNote(){const selected=[...state.selectedNotes],index=selected.length?Math.max(...selected)+1:state.notes.length,previous=state.notes[index-1]||state.notes[state.notes.length-1];addNote(previous?.name.replace(/[#b]$/,'')||'C',previous?.octave??4,index)}
function runEditorShortcut(action){const durations={durationWhole:'w',durationHalf:'h',durationQuarter:'q',durationEighth:'8',durationSixteenth:'16'};if(durations[action]){$(`[data-note="${durations[action]}"]`)?.click();return}if(action==='insertNextNote'){insertNextNote();return}if(action==='pitchUp'||action==='pitchDown'){moveSelectedPitch(action==='pitchUp'?1:-1);return}if(action==='moveLeft'||action==='moveRight'){reorderSelected(action==='moveLeft'?-1:1);return}if(action==='selectAll'){setSelected(state.notes.map((_,index)=>index));return}if(action==='delete'){removeSelectedNotes();return}if(action==='undo'){undo();return}if(action==='redo'){redo();return}if(action==='save'){saveScore($('#scoreComposition').value);return}if(action==='sharp'){applyAccidental('#');return}if(action==='flat'){applyAccidental('b');return}if(action==='natural'){applyAccidental('n');return}if(action==='beamSelection'){toggleBeamGroup();return}if(action==='crescendo'){applyHairpin('crescendo');return}if(action==='diminuendo'){applyHairpin('diminuendo');return}if(action.startsWith('tuplet'))startTuplet(Number(action.slice(6)))}
function initials(name='Usuario'){return name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
