function renderProjects(){const q=($('#projectSearch')?.value||'').toLowerCase(),f=$('#projectStatusFilter')?.value||'all';const ps=state.projects.filter(p=>(f==='all'||p.estado===f)&&p.nombre.toLowerCase().includes(q));$('#projectGrid').innerHTML=ps.length?ps.map(p=>projectCard(p)).join(''):'<div class="panel-card" style="grid-column:1/-1;text-align:center;padding:45px"><b>No hay proyectos todavía.</b><p style="font-size:10px;color:#847579">Crea tu primer proyecto para empezar a trabajar en Lyrics.</p></div>'}
