async function loadDashboard(){try{await loadProjects();const s=await api('/api/stats');const st=s.stats||{};$('#usageGrid').innerHTML=[['▱',st.proyectos||0,'Proyectos','En tu espacio'],['♩',st.grabaciones||0,'Grabaciones','Guardadas'],['♬',st.composiciones||0,'Composiciones','En tus proyectos'],['◷',st.analisis||0,'Análisis','Registrados']].map(x=>`<div class="usage-stat"><b>${x[1]}</b><span>${x[2]}</span><em>${x[3]}</em></div>`).join('');$('#activityRecent').innerHTML=(state.projects.length?state.projects.slice(0,4):[]).map(p=>`<div class="activity-row"><div class="activity-icon">♬</div><div><strong>${esc(p.nombre)}</strong><small>Actualizado · ${esc(p.fecha_actualizacion||'')}</small></div></div>`).join('')||'<div class="activity-row"><div><strong>Tu actividad aparecerá aquí</strong><small>Crea un proyecto para empezar.</small></div></div>';renderRecent()}catch(e){toast(e.message)}}
