function syncCompositionActions(){const hasProject=Boolean(state.currentProject),hasComposition=Boolean(state.currentComposition),composition=$('#scoreComposition'),metadataButton=$('#editScoreMetadataBtn'),addButton=$('#addCompositionBtn'),renameButton=$('#renameProjectBtn');if(composition)composition.disabled=!hasComposition;if(metadataButton){metadataButton.disabled=false;metadataButton.title=hasComposition?'Editar los datos impresos de esta partitura':'Editar datos como borrador; se guardarán en una composición cuando la crees o selecciones.'}if(addButton){addButton.disabled=false;addButton.title=hasProject?'Nueva composición':'Crear un proyecto y después una composición'}if(renameButton){renameButton.disabled=false;renameButton.textContent=hasProject?'✎':'＋';renameButton.title=hasProject?'Renombrar proyecto':'Crear proyecto';renameButton.setAttribute('aria-label',hasProject?'Renombrar proyecto':'Crear proyecto')}}
