function noteToVex(n){return `${(n.name||'C').toLowerCase()}/${n.octave??4}`}
function noteBeats(n){const base={w:4,h:2,q:1,'8':.5,'16':.25}[n.duration||'q']||1,actual=n.tuplet?.complete?Number(n.tuplet.actual)||1:1,normal=Number(n.tuplet?.normal)||1;return base*(n.dotted?1.5:1)*(actual>1&&normal>0?normal/actual:1)}
function scoreMeasures(){const capacity=state.meter.numerator*4/state.meter.denominator;const measures=[{indices:[],beats:0}];state.notes.forEach((note,index)=>{const beats=noteBeats(note);let bar=measures[measures.length-1];if(bar.indices.length&&bar.beats+beats>capacity+.001){bar={indices:[],beats:0};measures.push(bar)}bar.indices.push(index);bar.beats+=beats});return measures}
let tupletSequence=0;
function pruneBeamGroups(){const measures=scoreMeasures(),measureFor=index=>measures.findIndex(measure=>measure.indices.includes(index));state.beamGroups=state.beamGroups.filter(group=>group.length>1&&group.every((index,i)=>{const note=state.notes[index];return note&&!note.rest&&['8','16'].includes(note.duration)&&(i===0||index===group[i-1]+1&&measureFor(index)===measureFor(group[0]))}))}
function toggleBeamGroup(){const indices=[...state.selectedNotes].sort((a,b)=>a-b);if(indices.length<2)return toast('Selecciona al menos dos notas consecutivas para agrupar.');const measures=scoreMeasures(),measureFor=index=>measures.findIndex(measure=>measure.indices.includes(index));if(indices.some((index,i)=>{const note=state.notes[index];return !note||note.rest||!['8','16'].includes(note.duration)||(i>0&&(index!==indices[i-1]+1||measureFor(index)!==measureFor(indices[0])))}))return toast('Selecciona corcheas o semicorcheas consecutivas del mismo compás.');const existing=state.beamGroups.findIndex(group=>group.length===indices.length&&group.every((index,i)=>index===indices[i]));pushHistory();if(existing>=0){state.beamGroups.splice(existing,1);toast('Unión manual eliminada.')}else{state.beamGroups=state.beamGroups.filter(group=>!group.some(index=>indices.includes(index)));state.beamGroups.push(indices);toast('Figuras unidas.')}pruneBeamGroups();renderScore();dirtyScore()}
function eraseScoreNotes(indices,recordHistory=true,backward=false){const removed=[...new Set(indices)].filter(index=>Number.isInteger(index)&&index>=0&&index<state.notes.length).sort((a,b)=>a-b);if(!removed.length)return;const removedSet=new Set(removed),pendingGroupId=state.pendingTuplet?.groupId,removedPendingGroup=removed.some(index=>state.notes[index]?.tuplet?.groupId===pendingGroupId),countBefore=index=>removed.filter(value=>value<index).length,anchor=backward?Math.max(0,removed[0]-1):removed[0];if(recordHistory)pushHistory();removed.slice().reverse().forEach(index=>state.notes.splice(index,1));state.ties=state.ties.filter(pair=>!pair.some(index=>removedSet.has(index))).map(pair=>pair.map(index=>index-countBefore(index)));state.hairpins=state.hairpins.filter(item=>!removed.some(index=>index>=item.start&&index<=item.end)).map(item=>({...item,start:item.start-countBefore(item.start),end:item.end-countBefore(item.end)}));state.beamGroups=state.beamGroups.filter(group=>!group.some(index=>removedSet.has(index))).map(group=>group.map(index=>index-countBefore(index)));if(removedPendingGroup)state.pendingTuplet=null;pruneTuplets();pruneBeamGroups();state.selectedNotes=anchor<state.notes.length?new Set([anchor]):new Set();renderScore();updateTupletControls();dirtyScore()}
function updateTupletControls(){$$('[data-tuplet]').forEach(button=>{const active=state.pendingTuplet?.actual===Number(button.dataset.tuplet);button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));const label=button.querySelector('span');if(label)label.textContent=active?`Faltan ${state.pendingTuplet.remaining}`:button.dataset.tupletLabel})}
function startTuplet(actual){const normal={3:2,5:4,6:4,7:4,9:8}[actual];if(!normal)return toast('Ese grupo irregular no está disponible.');const indices=[...state.selectedNotes].sort((a,b)=>a-b),durations=new Set(indices.map(index=>state.notes[index]?.duration||state.selectedDuration)),duration=durations.size===1?[...durations][0]:state.selectedDuration,groupId=`tuplet-${Date.now()}-${++tupletSequence}`;if(indices.length&&indices.length!==actual)return toast(`Selecciona exactamente ${actual} notas o ninguna para insertar un grupo nuevo.`);if(indices.some((index,i)=>i>0&&index!==indices[i-1]+1))return toast('Selecciona notas consecutivas para agruparlas.');pushHistory();if(indices.length){indices.forEach(index=>{const note=state.notes[index];note.duration=duration;note.tuplet={actual,normal,groupId,complete:true}});state.pendingTuplet=null;state.selectedDuration=duration;renderScore();dirtyScore();toast(`Grupo de ${actual} aplicado a la selección.`)}else{state.selectedDuration=duration;state.pendingTuplet={actual,normal,duration,groupId,remaining:actual};toast(`Inserta ${actual} figuras de ${duration} para completar el grupo.`)}updateTupletControls()}
function pruneTuplets(){const groups=new Map();state.notes.forEach((note,index)=>{if(note.tuplet?.complete){if(!groups.has(note.tuplet.groupId))groups.set(note.tuplet.groupId,[]);groups.get(note.tuplet.groupId).push(index)}});groups.forEach((indices,groupId)=>{const actual=Number(state.notes[indices[0]]?.tuplet?.actual),valid=indices.length===actual&&indices.every((index,i)=>i===0||index===indices[i-1]+1);if(!valid)indices.forEach(index=>{if(state.notes[index]?.tuplet?.groupId===groupId)delete state.notes[index].tuplet})})}
function toggleAutoBeam(){pushHistory();state.autoBeam=!state.autoBeam;const button=$('#autoBeamBtn');button?.classList.toggle('active',state.autoBeam);button?.setAttribute('aria-pressed',String(state.autoBeam));renderScore();dirtyScore();toast(state.autoBeam?'Agrupación automática activada.':'Agrupación automática desactivada.')}
